using System.ComponentModel;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a summarization prompt for the given content.")]
    public static ChatMessage Summarize(
        [Description("The text content to summarize")] string content,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        return new ChatMessage(
            ChatRole.User,
            $$"""
            Please summarize the following content in a {{style}} style.

            Content:
            {{content}}
            """);
    }
}

